{"code":"await page.click('button[aria-label="تغيير اللغة"], .VPNavBarTranslations button');
const info = await page.evaluate(() => {
  const translations = document.querySelector('.VPNavBarTranslations');
  const button = translations?.querySelector('button');
  const menu = translations?.querySelector('.menu, .VPMenu, .items, [class*="menu"]');
  const flyout = translations?.querySelector('.VPFlyout');
  const flyoutMenu = translations?.querySelector('.VPFlyout .menu, .VPFlyout [class*="menu"], .VPMenu');

  // Also get computed styles of menu / flyoutMenu
  const target = flyoutMenu || menu;
  let computedStyle = null;
  if (target) {
    const cs = window.getComputedStyle(target);
    computedStyle = {
      position: cs.position,
      top: cs.top,
      right: cs.right,
      bottom: cs.bottom,
      left: cs.left,
      transform: cs.transform,
      width: cs.width,
    };
  }

  return {
    buttonRect: button ? button.getBoundingClientRect() : null,
    menuRect: target ? target.getBoundingClientRect() : null,
    windowWidth: window.innerWidth,
    computedStyle,
    targetHtml: target ? target.outerHTML.slice(0, 500) : null,
    flyoutHtml: flyout ? flyout.outerHTML.slice(0, 500) : null,
    translationsHtml: translations ? translations.outerHTML.slice(0, 800) : null,
  };
});
return info;
